\emph{\cite[Theorem 1]{Li-Ponnusamy-2013a}}
 Let $f=h+\overline{g}\in \mathscr{P}_{\mathcal{H}}^{0}(\alpha)$ be of the form 
 \begin{align}\label{eq.1} 
 	h(z)=z+\sum_{m=2}^{\infty} a_mz^m \ \text{and} \ g(z)=\sum_{m=2}^{\infty} b_mz^m.
 \end{align} 
 Then for each $m\ge 2$,
 \begin{align*}
 |b_m|\le \frac{1-\alpha}{m}.
 \end{align*}
 
 The result is sharp, with $f(z)=z+\frac{1-\alpha}{m}\,\overline{z^{m}}$
 being extremal.

\emph{\cite[Theorem 2]{Li-Ponnusamy-2013a}}
 Let $f=h+\overline{g}\in \mathscr{P}_{\mathcal{H}}^{0}(\alpha)$ and be of the form \emph{(\ref{eq.1})}. Then for any $m\ge 2$,
 	\par \emph{(i)} $|a_m|+|b_m|\le\frac{2(1-\alpha)}{m}$;
 	\par \emph{(ii)} $\bigl||a_m|-|b_m|\bigr|\le\frac{2(1-\alpha)}{m}$;
 	\par \emph{(iii)}	$|a_m|\le\frac{2(1-\alpha)}{m}$.
 	
 	All the results are sharp, with $(1-\alpha)\bigl(-z-2\log(1-z)\bigr)+\alpha z$
 	being the extremal.

\emph{\cite[Theorem 2.1]{Allu-Halder-2021}}
 	Let $f=h+\overline{g}\in\mathscr{P}_{\mathcal{H}}^{0}(\alpha)$ with $0\le\alpha<1$. Then
 	\begin{align*}
 	|z|
 	+\sum_{m=2}^{\infty}
 	\frac{2(1-\alpha)(-1)^{m-1}}{m}|z|^{m}
 	\le
 	|f(z)|
 	\le
 	|z|
 	+\sum_{m=2}^{\infty}
 	\frac{2(1-\alpha)}{m}|z|^{m}.
 	\end{align*}
 	Both the inequalities are sharp.

\emph{\cite[Theorem 2.2]{Allu-Halder-2021}}
	Let $f\in\mathcal{P}_{H}^{0}(\alpha)$ be given by \emph{(\ref{eq.1})} with
	$0\le \alpha<1$. Then the inequality
\begin{align*}
M_f(r):=|z|+\sum_{n=2}^{\infty}\left(|a_n|+|b_n|\right)|z|^n
\leq d\bigl(f(\mathbf{0}),\partial f(\mathbb{D})\bigr)
\end{align*}
holds for $|z|=r\le r_f$, where $r_f$ is the unique positive root of
\begin{align*}
	r+2(1-\alpha)\sum_{m=2}^{\infty}\frac{r^{m}}{m}
	=
	1+2(1-\alpha)\sum_{m=2}^{\infty}\frac{(-1)^{m-1}}{m}
\end{align*}
in $(0,1)$. The radius $r_f$ is the best possible.

For $\alpha$ with $0\leq \alpha<1$ and $z\in \mathbb{P} \Delta(0;1)$, let
	\begin{align*}
		\mathscr{P}_{\mathcal{H}_n^0}(\alpha)=\left\lbrace h+\overline g\in \mathcal{H}_n^0:\sum\limits_{k=1}^{\infty} \Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)>\sum\limits_{k=1}^{\infty}\left|\frac{\partial g(z)}{\partial z_k}\right| \right\rbrace.
	\end{align*}

\label{Th-1.2} Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$ and be given by \emph{(\ref{Eq 1.7})}. Then for any multi-index $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$, we have
\begin{align*}
\sum\limits_{|\beta|=m}|b_{\beta}|\leq n\binom{m+n-1}{n-1}\frac{1-\alpha}{m}
\end{align*}
The inequality is sharp.

Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$. Then
\begin{align}\label{Th2:1.1}
\sum\limits_{k=1}^{n}\Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)>\sum\limits_{k=1}^n\left|\frac{\partial g(z)}{\partial z_k}\right|
\end{align}
for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0_n;1_n)$. It follows from (\ref{Eq 1.7}) that
\begin{align}\label{Th2:1.2}
h(z)=\sum\limits_{j=1}^n z_j+\sum\limits_{m=2}^{\infty}P_m(z)\quad {and} \quad g(z)=\sum\limits_{m=2}^{\infty} Q_m(z)
\end{align}
for all $z\in \mathbb{P} \Delta(0_n;1_n)$, where
\begin{align}\label{Th2:1.3}
P_{m}(z)=\sum\limits_{|\beta|=m} a_{\beta} z^{\beta}\quad \text{and}\quad Q_m(z)=\sum\limits_{|\beta|=m} b_{\beta} z^{\beta}
\end{align}
are homogeneous polynomials of degree $m\geq 2$ in $z\in \mathbb{P} \Delta(0_n;1_n)$. We know that the number of terms in $\sum\limits_{|\beta|=m}$ is $\binom{|\beta|+n-1}{n-1}$. A simple computation using (\ref{Th2:1.3}) shows that
\begin{align}\label{Th2:1.3a}
\frac{\partial Q_m(z)}{\partial z_k}=\sum\limits_{|\beta|=m}\beta_{k} b_{\beta}z_1^{\beta_1}\ldots z_{j-1}^{\beta_{j-1}}z_{j}^{\beta_j}z_{j+1}^{\beta_{j+1}}\ldots z_{k-1}^{\beta_{k-1}}z_{k}^{\beta_{k}-1}z_{k+1}^{\beta_{k+1}}\ldots z_n^{\beta_n}
\end{align}


Using (\ref{Th2:1.2}) together with (\ref{Th2:1.3a}), we get
\begin{align}\label{Th2:1.5a}
\frac{\partial g(z)}{\partial z_k}&=
\sum\limits_{m=2}^{\infty} \frac{\partial Q_m(z)}{\partial z_k}\\=&\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}\beta_{k} b_{\beta}z_1^{\beta_1}\ldots z_{j-1}^{\beta_{j-1}}z_{j}^{\beta_j}z_{j+1}^{\beta_{j+1}}\ldots z_{k-1}^{\beta_{k-1}}z_{k}^{\beta_{k}-1}z_{k+1}^{\beta_{k+1}}\ldots z_n^{\beta_n}.\nonumber
\end{align}

By applying Cauchy's integral formula to $\frac{\partial g(z)}{\partial z_k}$, it follows from \eqref{Th2:1.5a} that
\begin{align}\label{Th2:1.6a}
&(2\pi i)^n \beta_{k}b_{\beta}\\=&\int\limits_{|z_1|=r_1}\ldots \int\limits_{|z_n|=r_n}\frac{\frac{\partial g(z)}{\partial z_k}\;dz_1\;d z_2\ldots d z_n}{z_1^{\beta_1+1}\ldots z_{j-1}^{\beta_{j-1}+1}z_{j}^{\beta_j+1}z_{j+1}^{\beta_{j+1}+1}\ldots z_{k-1}^{\beta_{k-1}+1}z_{k}^{\beta_{k}}z_{k+1}^{\beta_{k+1}+1}\ldots z_n^{\beta_n+1}}.\nonumber
\end{align}
where $0<r_j<1$ for $j=1,2,\ldots,n$. We set $z=\left(re^{\iota\theta_1},re^{\iota\theta_2},\ldots,re^{\iota\theta_n}\right)$, where $0\leq \theta_j\leq 2\pi$, $j=1,2,\ldots,n$.
Now from (\ref{Th2:1.6a}), we have
\begin{align}\label{Th2:1.6b}
(2\pi i)^n \beta_{k}|b_{\beta}|\leq \int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\frac{\left|\frac{\partial g(z)}{\partial z_k}\right|\;d\theta_1 d\theta_2\ldots d\theta_n}{r^{m-1}}
\end{align}
and so
\begin{align}\label{Th2:1.7}
(2\pi)^n\sum\limits_{|\beta|=m}\beta_k|b_{\beta}|\leq \binom{|\beta|+n-1}{n-1}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\frac{\left|\frac{\partial g(z)}{\partial z_k}\right|\;d\theta_1d\theta_2\ldots d\theta_n}{r^{m-1}}
\end{align}
for all $k=1,2,\ldots,n$. Consequently from (\ref{Th2:1.7}), we obtain
\begin{align}\label{Th2:1.8}
(2\pi)^nr^{m-1} \sum\limits_{k=1}^n\sum\limits_{|\beta|=m} \beta_k|b_{\beta}|=&
(2\pi)^nr^{m-1} \sum\limits_{|\beta|=m}|b_{\beta}|\sum\limits_{k=1}^n \beta_k\\ \leq &\binom{|\beta|+n-1}{n-1}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\sum\limits_{k=1}^n\left|\frac{\partial g(z)}{\partial z_k}\right|\;d\theta_1d\theta_2\ldots d\theta_n.\nonumber
\end{align}
However, we observe that 
\begin{align}\label{Th2:1.8a}
\sum\limits_{|\beta|=m}|b_{\beta}|\sum\limits_{k=1}^n\beta_{k}=m\sum\limits_{|\beta|=m}|b_{\beta}|.
\end{align}

Using (\ref{Th2:1.8a}) together with (\ref{Th2:1.8}), we get
\begin{align}\label{Th2:1.8b}
(2\pi)^nr^{m-1}m \sum\limits_{|\beta|=m}|b_{\beta}|
 \leq \binom{|\beta|+n-1}{n-1}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\sum\limits_{k=1}^n\left|\frac{\partial g(z)}{\partial z_k}\right|\;d\theta_1 d\theta_2\ldots d\theta_n.
\end{align}

Moreover, we know that
\begin{align}\label{Th2:1.8c}
&\frac{\partial h(z)}{\partial z_k}\\=&1+
\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}\beta_{k} a_{\beta}z_1^{\beta_1}\ldots z_{j-1}^{\beta_{j-1}}z_{j}^{\beta_j}z_{j+1}^{\beta_{j+1}}\ldots z_{k-1}^{\beta_{k-1}}z_{k}^{\beta_{k}-1}z_{k+1}^{\beta_{k+1}}\ldots z_n^{\beta_n}.\nonumber
\end{align}

For any multi-index $\nu=(\nu_1,\nu_2,\ldots,\nu_n)$, we have
\begin{align}\label{Th2:1.9}
\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi} (e^{i\theta_1})^{\nu_1}\ldots (e^{i\theta_n})^{\nu_n}d\theta_1 \ldots d\theta_n=
\begin{cases}
0,& \nu\neq (0,0,\ldots,0),\\[2ex]
(2\pi)^n,& \nu=(0,0,\ldots,0).
\end{cases}
\end{align}

Using (\ref{Th2:1.9}) together with (\ref{Th2:1.8c}), we deduce that
\begin{align*}
\frac{1}{(2\pi)^n}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)\;d\theta_1\;d \theta_2\ldots d \theta_n=1-\alpha
\end{align*}
and so we get
\begin{align*}
\frac{1}{(2\pi)^n}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)\;d\theta_1\;d \theta_2\ldots d \theta_n=1-\alpha.
\end{align*}
Consequently
\begin{align}\label{Th2:1.9a}
\frac{1}{(2\pi)^n}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi} \sum\limits_{k=1}^n\Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)\;d\theta_1\;d \theta_2\ldots d \theta_n=n(1-\alpha).
\end{align}
In view of (\ref{Th2:1.1}) and (\ref{Th2:1.9a}) and using (\ref{Th2:1.8b}), we obtain
\begin{align*}
&r^{m-1}m\sum\limits_{|\beta|=m}|b_{\beta}|
\\ \leq &\binom{|\beta|+n-1}{n-1}\frac{1}{(2\pi)^n}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\sum\limits_{k=1}^n\left|\frac{\partial g(z)}{\partial z_k}\right|\;d\theta_1\;d \theta_2\ldots d \theta_n\\\leq &
\binom{|\beta|+n-1}{n-1}\frac{1}{(2\pi)^n}\int\limits_{0}^{2\pi}\ldots \int\limits_0^{2\pi}\sum\limits_{k=1}^n\Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)\;d\theta_1\;d \theta_2\ldots d \theta_n\\\leq&n
\binom{|\beta|+n-1}{n-1}(1-\alpha).
\end{align*}

Letting $r\to 1^-$, we obtain
\begin{align*}
\sum\limits_{|\beta|=m}|b_{\beta}|\leq n\binom{m+n-1}{n-1}\frac{1-\alpha}{m}
\end{align*}
if $m\geq 2$.\vspace{1.2mm}

To show that the bound is sharp, we consider the following function
\begin{align*}
f_1(z)=\sum\limits_{j=1}^n z_j+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m} b_{\beta} \overline{z^{\beta}},
\end{align*}
where $b_{\beta}=\frac{n(1-\alpha)}{m}$
for all multi-index $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m$. 
A direct computation shows that $f_1\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$, and 
\begin{align*}
\sum\limits_{|\beta|=m}|b_{\beta}(f_1)|=n\binom{m+n-1}{n-1}\frac{1-\alpha}{m}.
\end{align*}

\label{Lm-3.1}\emph{\cite[Theorem 6.1.4]{Graham-Kohr}} Let $f$ be holomorphic in the polydisk $\mathbb{P}\Delta(0_n;1_n)$ such that $|f(z)|\leq 1$ for all $z\in \mathbb{P}\Delta(0_n;1_n)$. Then
\begin{align*}
\left|\frac{\partial^{|\beta|} f(0)}{\partial z_1^{\beta_1}\ldots \partial z_n^{\beta_n}}\right|\leq \beta!
\end{align*}
 for multi-index $\beta=(\beta_1,\ldots, \beta_n)$.

\label{Th-1.3} Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$ and be given by \emph{(\ref{Eq 1.7})}. Then for any multi-index $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$, we have
\begin{enumerate}
\item[\emph{(i)}] $\displaystyle \left|\sum\limits_{|\beta|=m}a_{\beta}\right|+\left|\sum\limits_{|\beta|=m}b_{\beta}\right|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}$,\vspace{1.2mm}
\item[\emph{(ii)}] $\displaystyle \left|\;\left|\sum\limits_{|\beta|=m}a_{\beta}\right|-\left|\sum\limits_{|\beta|=m}b_{\beta}\right|\;\right|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}$,\vspace{1.2mm}
\item[\emph{(iii)}] 
$\displaystyle \left|\sum\limits_{|\beta|=m}a_{\beta}\right|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}$.
\end{enumerate}
All three inequalities are sharp.

Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$. Note that 
\begin{align*}
\displaystyle \sum\limits_{k=1}^n\Re\left(\frac{\partial h(z)}{\partial z_k}+\varepsilon \frac{\partial g(z)}{\partial z_k}-\alpha\right)=&
\sum\limits_{k=1}^n\Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)+\sum\limits_{k=1}^n\Re\left(\varepsilon \frac{\partial g(z)}{\partial z_k}\right)\\>&
\sum\limits_{k=1}^n\Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)-\sum\limits_{k=1}^n\left|\varepsilon \frac{\partial g(z)}{\partial z_k}\right|\\=&
\sum\limits_{k=1}^n\Re\left(\frac{\partial h(z)}{\partial z_k}-\alpha\right)-\sum\limits_{k=1}^n\left|\frac{\partial g(z)}{\partial z_k}\right|
\end{align*}
for all $\varepsilon\in\mathbb{C}$ such that $|\varepsilon|=1$. Therefore from \eqref{Th2:1.1}, we deduce that 
\begin{align}\label{Th3:1.1}
\displaystyle\Re\left(\sum\limits_{k=1}^n\left(\frac{\partial h(z)}{\partial z_k}+\varepsilon \frac{\partial g(z)}{\partial z_k}\right)\right)-n\alpha=\sum\limits_{k=1}^n\Re\left(\frac{\partial h(z)}{\partial z_k}+\varepsilon \frac{\partial g(z)}{\partial z_k}-\alpha\right)>0
\end{align}
for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0_n;1_n)$. Let $F_{\varepsilon}(z)=h(z)+\varepsilon g(z)$. Clearly
\begin{align*}
\displaystyle F_{\varepsilon}(z)=\sum\limits_{j=1}^n z_j+\sum\limits_{m=2}^{\infty}\left(P_m(z)+\varepsilon Q_m(z)\right),
\end{align*}
for all $z\in \mathbb{P} \Delta(0_n;1_n)$, where $P_m(z)$ and $Q_m(z)$ are defined in (\ref{Th2:1.3}). Note that
 \begin{align*}
 \displaystyle \frac{\partial F_{\varepsilon}(z)}{\partial z_k}=&1+
 \sum\limits_{m=2}^{\infty} \frac{\partial \left(P_m(z)+\varepsilon Q_m(z)\right)}{\partial z_k}\\=&1+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}\beta_{k} c_{\beta}z_1^{\beta_1}\ldots z_{j-1}^{\beta_{j-1}}z_{j}^{\beta_j}z_{j+1}^{\beta_{j+1}}\ldots z_{k-1}^{\beta_{k-1}}z_{k}^{\beta_{k}-1}z_{k+1}^{\beta_{k+1}}\ldots z_n^{\beta_n},
 \end{align*}
where 
$c_{\beta}=a_{\beta}+\varepsilon b_{\beta}$.
Consequently
\begin{align}\label{Th3:1.2}
\displaystyle &\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(z)}{\partial z_k}\\ =&n+
\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}\sum\limits_{k=1}^n\beta_{k} c_{\beta}z_1^{\beta_1}\ldots z_{j-1}^{\beta_{j-1}}z_{j}^{\beta_j}z_{j+1}^{\beta_{j+1}}\ldots z_{k-1}^{\beta_{k-1}}z_{k}^{\beta_{k}-1}z_{k+1}^{\beta_{k+1}}\ldots z_n^{\beta_n}\nonumber
\end{align}
for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0_n;1_n)$. Then from (\ref{Th3:1.1}), we see that
\begin{align*} \Re\left(\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(z)}{\partial z_k}\right)-n\alpha>0\;\;\text{and}\;\;\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(0)}{\partial z_k}-n\alpha=n(1-\alpha).
\end{align*}
Therefore, there exists a function \begin{align}\label{Th3:1.3}
	P(z)=1+\sum\limits_{m=1}^{\infty}\sum\limits_{|\beta|=m}P_{\beta}z^{\beta}
\end{align}
 such that
\begin{align}\label{Th3:1.4}
\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(z)}{\partial z_k}=n+n(1-\alpha)\sum\limits_{m=1}^{\infty}\sum\limits_{|\beta|=m}P_{\beta}z^{\beta}
\end{align}
for all $z\in \mathbb{P}\Delta(0_n;1_n)$, where $P(z)$ is holomorphic in $\mathbb{P}\Delta(0_n;1_n)$ and $\Re(P(z))>0$ in $\mathbb{P}\Delta(0_n;1_n)$. 

Let $\omega_l=e^{\frac{2\pi \iota}{k}l}$, where $k\geq 1$ is an integer. We see that $\sum_{l=1}^k \omega_l^s=0$ if $s\leq k-1$. Let
\begin{align*}
	\tilde g(z)=\frac{1}{k}\sum\limits_{l=1}^k P\left(\omega_l z\right).
\end{align*}

The function $\tilde g$ is clearly holomorphic in $\mathbb{P}\Delta(0_n;1_n)$ such that $\Re\{\tilde g(z)\} > 0$ throughout the domain. Furthermore, we see that $\tilde g(0) =1$ and $\tilde g$ has the series expansion
\begin{align*}
	\tilde g(z)=1+\sum\limits_{m=1}^{\infty}\sum\limits_{|\beta|=mk} P_{\beta}z^{\beta}
\end{align*}
for all $z\in \mathbb{P}\Delta(0_n;1_n)$. Let
\begin{align}
	\label{Eq-3.20}\phi(z)=\frac{\tilde g(z)-1}{\tilde g(z)+1}
\end{align}
for all $z\in \mathbb{P}\Delta(0_n;1_n)$. One can easily verify that $|\phi(z)|<1$ for all $z\in \mathbb{P}\Delta(0_n;1_n)$ and $k$ is the zero-multiplicity of $\phi$ at $0$. We expand $\phi(z)$ to a Taylor series with multi-index $\beta$,
\begin{align}
	\label{Eq-3.21} \phi(z)=\sum\limits_{m=k}^{\infty}\sum\limits_{|\beta|=m}Q_{\beta}z^{\beta}
\end{align}
By Lemma \ref{Lm-3.1}, we have $|Q_{\beta}|\leq 1$
              
                                  
            
for multi-index $\beta$. Now from \eqref{Eq-3.20} and \eqref{Eq-3.21}, we deduce that
\begin{align*}
	\sum\limits_{|\beta|=k} P_{\beta}z^{\beta}+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=mk} P_{\beta}z^{\beta}&=2 \sum\limits_{m=k}^{\infty}\sum\limits_{|\beta|=m}Q_{\beta}z^{\beta}\\&+
	\left(\sum\limits_{|\beta|=k} P_{\beta}z^{\beta}+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=mk} P_{\beta}z^{\beta}\right)\left(\sum\limits_{m=k}^{\infty}\sum\limits_{|\beta|=m}Q_{\beta}z^{\beta}\right).
\end{align*}
It then follows that
\begin{align}
	\label{Eq-3.23} \sum\limits_{|\beta|=k} \left(P_{\beta}-2Q_{\beta}\right)z^{\beta}+\text{higher degree terms of}\; (z_1^{\beta_1},\ldots,z_n^{\beta_n})\equiv 0
\end{align}
holds for all $z\in \mathbb{P}\Delta(0_n;1_n)$. Comparing the homogeneous terms of degree $k$ in
\eqref{Eq-3.23},
we obtain 
\begin{align}
	\label{Eq-3.24}\sum\limits_{|\beta|=k} \left(P_{\beta}-2Q_{\beta}\right)=0.
\end{align}
\noindent Since $|Q_{\beta}|\leq 1$ for multi-index $\beta$, from \eqref{Eq-3.24}, we conclude that
\begin{align}\label{Th3:1.5}
	\sum\limits_{|\beta|=k} |P_{\beta}|\leq 2\sum\limits_{|\beta|=k} |Q_{\beta}|\leq 2\sum\limits_{|\beta|=k} 1\leq 2\binom{k+n-1}{n-1},
\end{align}
where $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=k$. \vspace{1.2mm}


On the other hand, from (\ref{Th3:1.2}) and (\ref{Th3:1.4}), we obtain
\begin{align}\label{Th3:1.6}
&\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}\sum\limits_{k=1}^n\beta_{k} c_{\beta}z_1^{\beta_1}\ldots z_{j-1}^{\beta_{j-1}}z_{j}^{\beta_j}z_{j+1}^{\beta_{j+1}}\ldots z_{k-1}^{\beta_{k-1}}z_{k}^{\beta_{k}-1}z_{k+1}^{\beta_{k+1}}\ldots z_n^{\beta_n}\\=&n(1-\alpha)\sum\limits_{m=1}^{\infty}\sum\limits_{|\beta|=m}P_{\beta}z^{\beta}\nonumber
\end{align}
where $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$. Putting $z_1=z_2=\ldots=z_n=z$ on both sides of \eqref{Th3:1.6} and then comparing coefficients, we get
\begin{align*}
\sum\limits_{|\beta|=m}\sum\limits_{k=1}^n
\beta_kc_{\beta}=n(1-\alpha)\sum\limits_{|\beta|=m}P_{\beta}
\end{align*}
and so from \eqref{Th3:1.5}, we get
\begin{align}\label{Th3:1.7}
\left|\sum\limits_{|\beta|=m}a_{\beta}+\varepsilon\sum\limits_{|\beta|=m} b_{\beta}\right|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}
\end{align}
for all $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$ and for all $\varepsilon$ such that $|\varepsilon|=1$. 
	
Suppose $A_{\beta}=\sum\limits_{|\beta|=m}a_\beta\neq 0$ and $B_{\beta}=\sum\limits_{|\beta|=m}b_\beta\neq 0$. If we choose 
\begin{align*}
\varepsilon=\frac{A_{\beta}}{|A_{\beta}|}\frac{\overline B_{\beta}}{|B_{\beta}|},
\end{align*}
then $|\varepsilon|=1$ and so from (\ref{Th3:1.7}), we have
\begin{align}\label{Th3:1.8}
|A_{\beta}+\varepsilon B_{\beta}|=|A_{\beta}|+|B_{\beta}|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}
\end{align}
for $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$. If either $A_{\beta}=0$ or $B_{\beta}=0$, then (\ref{Th3:1.8}) also holds. Therefore, we have
\begin{align}\label{Th3:1.8a}
\left|\sum\limits_{|\beta|=m}a_{\beta}\right|+\left|\sum\limits_{|\beta|=m}b_{\beta}\right|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}
\end{align}
for $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$.

On the other hand, we have
\begin{align*}
\left||A_{\beta}|-|B_{\beta}|\right|\leq |A_{\beta}+\varepsilon B_{\beta}|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}
\end{align*}
for $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$. Consequently
\begin{align*}
\left|\;\left|\sum\limits_{|\beta|=m}a_{\beta}\right|-\left|\sum\limits_{|\beta|=m}b_{\beta}\right|\;\right|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}
\end{align*}
for $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$.
	

It is clear from \eqref{Th3:1.8a} that 
\begin{align*}
\left|\sum\limits_{|\beta|=m}a_{\beta}\right|\leq 2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m},
\end{align*}
where $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$.\vspace{1.2mm}

	
To show all the inequalities are sharp, we consider the following function
\begin{align}\label{Ex1}
f_2(z)=\sum\limits_{j=1}^n z_j+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m} a_{\beta} z^{\beta},
\end{align}
where 
\begin{align*}
a_{\beta}=\frac{2n(1-\alpha)}{m}
\end{align*}
for all multi-index $\beta=(\beta_1,\beta_2,\ldots,\beta_n)$ such that $|\beta|=m$. 
A direct computation shows that $f_2\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$, and 
\begin{align*}
\sum\limits_{|\beta|=m}|a_{\beta}(f_2)|=2\binom{m+n-1}{n-1}\frac{n(1-\alpha)}{m}.
\end{align*}

\label{Th-1.4}Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$ with $0<\alpha\leq 1$ and be given by \emph{(\ref{Eq 1.7})}. Then for $z\in \mathbb{P} \Delta(0_n;1_n)$, we have
\begin{align*}
	\left|\sum\limits_{j=1}^nz_j\right|+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
	(-1)^{m-1}\frac{\|z\|_{\infty}^m}{m}\leq |f(z)|\leq n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
	\frac{\|z\|_{\infty}^m}{m}.
\end{align*}
 Both the inequalities are sharp.

Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$. Let $F_{\varepsilon}=h+\varepsilon g$. Then from (\ref{Th3:1.1}), we see that
\begin{align*} \Re\left(\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(z)}{\partial z_k}\right)-n\alpha>0\;\;\text{and}\;\;\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(0)}{\partial z_k}-n\alpha=n(1-\alpha)
\end{align*}
for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0_n;1_n)$. Then there exists a holomorphic function $\omega(z)$ with $\omega(0)=0$ and $|\omega(z)|<1$ for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0_n;1_n)$ such that
\begin{align*}
\frac{\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(z)}{\partial z_k}-n\alpha}{n(1-\alpha)}=\frac{1+\omega(z)}{1-\omega(z)}
\end{align*} 
or equivalently 
\begin{align}\label{Th4:1.1}	
	\sum\limits_{k=1}^n\frac{\partial F_{\varepsilon}(z)}{\partial z_k}=n\alpha+n(1-\alpha)\frac{1+\omega(z)}{1-\omega(z)}
\end{align}
for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0_n;1_n)$.	
Also by Lemma 6.1.28 \cite{Graham-Kohr}, we have
\begin{align}\label{Th4:1.1a}
|\omega(z)|\leq \|z\|_{\infty}
\end{align}
for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0_n;1_n)$.\vspace{1.2mm}


Let $z\in \mathbb{P}\Delta(0_n;1_n)$ be fixed in such a way that $z\neq 0$. Obviously $\|z\|_{\infty}<1$. 

We define 
\begin{align}\label{Th4:1.2}
	\tilde h(t)=h\left(\frac{z}{||z||_{\infty}}t\right)=\frac{1}{||z||_{\infty}}\left(\sum\limits_{j=1}^n z_j\right)t+\sum\limits_{m=2}^{\infty}P_m\left(\frac{z}{||z||_{\infty}}\right)t^m
\end{align}
and
\begin{align}\label{Th4:1.3}
	\tilde g(t)=g\left(\frac{z}{||z||_{\infty}}t\right)=\sum\limits_{k=2}^{\infty} Q_m\left(\frac{z}{||z||_{\infty}}\right)t^m,
\end{align}
where $h(z)$ and $g(z)$ are defined by (\ref{Th2:1.2}) and $t\in\mathbb{C}$ such that $|t|<1$. For a fixed $z\in \mathbb{P}\Delta(0_n;1_n)$, we can say that $\tilde g(t)$ and $\tilde h(t)$ are analytic in $|t|<1$. Obviously for a fixed $z\in \mathbb{P}\Delta(0_n;1_n)$, the following function
\begin{align}\label{Th4:1.4}
	\tilde F_{\varepsilon}(t)=F_{\varepsilon}\left(\frac{z}{||z||_{\infty}}t\right)=\tilde h(t)+\varepsilon \tilde g(t)
\end{align}
is analytic in $|t|<1$, where $\tilde h(t)$ and $\tilde g(t)$ are defined by (\ref{Th4:1.2}) and (\ref{Th4:1.3}). Also from (\ref{Th4:1.2}) and (\ref{Th4:1.3}), we see that
\begin{align}\label{Th4:1.5}
	\tilde f(t)=f\left(\frac{z}{||z||_{\infty}}t\right)=\tilde h(t)+\overline{\tilde g(t)}.
\end{align}

We define 
\begin{align}\label{Th4:1.6}
	\tilde \omega(t)=\omega\left(\frac{z}{||z||_{\infty}}t\right),
\end{align}
which is analytic in $|t|<1$. Consequently from \eqref{Th4:1.1a}, we have
\begin{align}\label{Th4:1.6a}
	|\tilde \omega(t)|\leq |t|.
\end{align}

In terms of one variable $t$, we deduce from (\ref{Th4:1.2}) that
\begin{align}\label{Th4:1.7}
	\frac{d \tilde F_{\varepsilon}(t)}{d t}=n\alpha+n(1-\alpha)\frac{1+\tilde \omega(t)}{1-\tilde \omega(t)}.
\end{align}
	
Note that
\begin{align}\label{Th4:1.8}
\tilde F_{\varepsilon}(t)=\tilde F_{\varepsilon}(t)-\tilde F_{\varepsilon}(0)=\int\limits_{0}^{t} \frac{d \tilde F_{\varepsilon}(s)}{d s} ds.
\end{align}


Now using  (\ref{Th4:1.6a}) and \eqref{Th4:1.7} into (\ref{Th4:1.8}), we obtain
\begin{align*}
\left|\tilde F_{\varepsilon}\left(\|z\|_{\infty}\right)\right|=
\left|\int\limits_{0}^{\|z\|_{\infty}}\frac{d \tilde F_{\varepsilon}(s)}{d s}ds\right|
\leq & 
\int\limits_{0}^{\|z\|_{\infty}}\left(n\alpha+n(1-\alpha)\left|\frac{1+\tilde \omega(\xi e^{i\theta})}{1-\tilde \omega(\xi e^{i\theta})}\right|\right)d \xi\\\leq & 
\int\limits_{0}^{\|z\|_{\infty}}\left(n\alpha+n(1-\alpha)\frac{1+\xi}{1-\xi}\right)d \xi
\nonumber\\ =&
\int\limits_{0}^{\|z\|_{\infty}} \left(n+2n(1-\alpha)\left(\xi+\xi^2+\xi^3+\ldots\right)\right)d\xi\nonumber\\= &
n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
\frac{\|z\|_{\infty}^m}{m}\nonumber
\end{align*}
and so from \eqref{Th4:1.4}, we get
\begin{align}\label{Th4:1.9}
|F_{\varepsilon}(z)|\leq n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
\frac{\|z\|_{\infty}^m}{m},
\end{align}
which also holds for $z=0$.

Again using (\ref{Th4:1.6a}) and \eqref{Th4:1.7} into (\ref{Th4:1.8}), we obtain
\begin{align*}
	\left|\tilde F_{\varepsilon}\left(\|z\|_{\infty}\right)\right|
	\geq & 
	\int\limits_{0}^{\|z\|_{\infty}}\left(n\alpha+n(1-\alpha)\Re\left(\frac{1+\tilde \omega(\xi e^{i\theta})}{1-\tilde \omega(\xi e^{i\theta})}\right)\right)d \xi\\\geq & 
	\int\limits_{0}^{\|z\|_{\infty}}\left(n\alpha+n(1-\alpha)\frac{1-\xi}{1+\xi}\right)d \xi
	\nonumber\\ =&
	\int\limits_{0}^{\|z\|_{\infty}} \left(n+2n(1-\alpha)\left(-\xi+\xi^2-\xi^3+\ldots\right)\right)d\xi\nonumber\\= &
	n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
	(-1)^{m-1}\frac{\|z\|_{\infty}^m}{m}\nonumber
\end{align*}
and so from \eqref{Th4:1.4}, we get
\begin{align}\label{Th4:1.10}
	|F_{\varepsilon}(z)|\geq n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
	(-1)^{m-1}\frac{\|z\|_{\infty}^m}{m},
\end{align}
which also holds for $z=0$.

Since $|\sum_{j=1}^nz_j|\leq n\|z\|_{\infty}$, from \eqref{Th4:1.9} and \eqref{Th4:1.10}, we get
\begin{align*}
\left|\sum\limits_{j=1}^nz_j\right|+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
(-1)^{m-1}\frac{\|z\|_{\infty}^m}{m}\leq |F_{\varepsilon}(z)|\leq n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
\frac{\|z\|_{\infty}^m}{m}.
\end{align*}

Finally since $\varepsilon\; (|\varepsilon|=1)$ is arbitrary and $F_{\varepsilon}(z)=h(z)+\varepsilon g(z)$, for each $0\leq \alpha<1$, we have
\begin{align*}
	\left|\sum\limits_{j=1}^nz_j\right|+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
	(-1)^{m-1}\frac{\|z\|_{\infty}^m}{m}\leq |f(z)|\leq n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
	\frac{\|z\|_{\infty}^m}{m}.
\end{align*}


Thus the desired inequalities are established.\vspace{2mm}
	
To show the left inequality is sharp, we consider the function $f_3(z)$ defined by
	\begin{align*}
		f_3(z)=\sum\limits_{j=1}^n z_j+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}a_{\beta}z^{\beta},
	\end{align*}
	where
	\begin{align*}
		a_{\beta}=(-1)^{|\beta|-1}\frac{2n(1-\alpha)}{\binom{m+n-1}{n-1}m}
	\end{align*}
	for $\beta=(\beta_1,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$. It is easy to verify that $f_3\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$. 
	
	Now for the point $z=(r,r,\ldots,r)$, where $0<r<1$, we find that
	\begin{align*}
		|f_3(z)|=&nr+2n(1-\alpha)\sum\limits_{m=2}^{\infty}(-1)^{m-1}\frac{r^m}{\binom{m+n-1}{n-1}m}\sum\limits_{|\beta|=m} 1\\=&
		nr+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{m}r^m\\=&
		\left|\sum\limits_{j=1}^nz_j\right|+2n(1-\alpha)\sum\limits_{m=2}^{\infty}(-1)^{m-1}\frac{\|z\|_{\infty}^{m}}{m}.
	\end{align*}
	Therefore the left inequality is sharp.\vspace{1.2mm}
	
	Next to show the right inequality is sharp, we consider the function $f_4(z)$ defined by
	\begin{align*}
		f_4(z)=\sum\limits_{j=1}^n z_j+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}b_{\beta}z^{\beta},
	\end{align*}
	where
	\begin{align*}
		b_{\beta}=\frac{2n(1-\alpha)}{\binom{m+n-2}{n-1}m}
	\end{align*}
	for $\beta=(\beta_1,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$. It is easy to verify that $f_4\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$.
	
	For the point $z=(r,r,\ldots,r)$, where $r<1$, we have
	\begin{align*}
		|f_4(z)|=n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{||z||_{\infty}^m}{m},
	\end{align*}
	which shows that the right inequality is sharp.

\label{Th-1.5} Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$ be given by \emph{(\ref{Eq 1.7})} with $0<\alpha\leq 1$. Then the inequality \eqref{Eq 1.8} holds for all $z=(z_1,z_2,\ldots,z_n)\in \mathbb{P} \Delta(0;1/n)$ such that $\|z\|_{\infty}={\bf{r}}\leq {\bf{r}_f}$ and $n{\bf{r}}$ is the unique positive root of 
\begin{align*}
 n{\bf{r}}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(n{\bf{r}})^m}{m}=1+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{mn^m}
 \end{align*}
in $(0,1)$. The radius ${\bf{r}_f}$ is the best possible.

Let $f\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$. 
Then by Theorem \ref{Th-1.4}, we have 
\begin{align}\label{Th5:1.1}
|f(z)|\geq \left|\sum\limits_{j=1}^nz_j\right|+2n(1-\alpha)\sum\limits_{m=2}^{\infty}
(-1)^{m-1}\frac{\|z\|_{\infty}^m}{m}
\end{align}
for all $z\in \mathbb{P}\Delta(0;1/n)$.
By taking $\liminf$ as $(|z_1|,|z_2|,\ldots,|z_n|)\to (1/n,1/n,\ldots,1/n)$ on both sides of \eqref{Th5:1.1}, we obtain
\begin{align}\label{Th5:1.2}
\liminf\limits_{(|z_1|,|z_2|,\ldots,|z_n|)\to (1/n,1/n,\ldots,1/n)}|f(z)|\geq 1+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{m n^m}
\end{align}

The Euclidean distance between $f(0)$ and the boundary of $f(\mathbb{P}\Delta(0;1/n))$ is given by
\begin{align}\label{Th5:1.3}
	d\left(f(0),\partial f(\mathbb{P}\Delta(0;1/n))\right)=\liminf\limits_{(|z_1|,|z_2|,\ldots,|z_n|)\to (1/n,1/n,\ldots,1/n)}|f(z)-f(0)|.
\end{align}
Since $f(0)=0$, from (\ref{Th5:1.2}) and (\ref{Th5:1.3}), we get
 \begin{align}\label{Th5:1.4}
 d\left(f(0),\partial f(\mathbb{P}\Delta(0;1/n))\right)\geq 1+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{m n^m}.
 \end{align}
 
 Let $H_1:[0,1)\to \mathbb{R}$ be defined by
 \begin{align*}
 H_1(n{\bf{r}})=&n{\bf{r}}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(n{\bf{r}})^m}{m}-1-2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{mn^m}\\=&n{\bf{r}}-2n(1-\alpha)(n{\bf{r}}+\log (1-n{\bf{r}}))-1-2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{mn^m}.
 \end{align*}
 
 Note that
 \begin{align*}
 	H_1(0)=-1-2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{mn^m}=-1-2n(1-\alpha)(\log (1+1/n)-1/n)<0
 \end{align*}
 for all $\alpha\in [0,1)$ and. On the other hand, we see that $H_1(n{\bf{r}})\to +\infty$ as $n{\bf{r}}\to 1$ and 
 \begin{align*}
 \frac{d H_1(n{\bf{r}})}{d n{\bf{r}}}=1+2n(1-\alpha)\frac{n{\bf{r}}}{1-n{\bf{r}}}>0
 \end{align*}
 for $n{\bf{r}}\in (0,1)$. 
 
 This shows that $H_1(n{\bf{r}})$ is strictly increasing on $(0,1)$.
