 For $0\leq n{\bf{r}}\leq n{\bf{r}}_f$, we deduce from (\ref{Th5:1.5}) that 
 \begin{align}\label{Th5:1.6}
 n{\bf{r}}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(n{\bf{r}})^m}{m}\leq&\; n{\bf{r}}_f+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(n{\bf{r}}_f)^m}{m}\\=&1+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{mn^m}.\nonumber
 \end{align}
 
 Let $z\in \mathbb{P}\Delta(0;1/n)$ such that $r=(|z_1|,|z_2|,\ldots,|z_n|)=(r_1,r_2,\ldots,r_n)$ and ${\bf{r}}=\|z\|_{\infty}$. 
Using Theorem \ref{Th-1.3} and the inequalities \eqref{Th5:1.4} and \eqref{Th5:1.6}, for $0\le n\|z\|_{\infty}=n{\bf{r}}\leq n{\bf{r}}_f$, we deduce that 
 \begin{align*}
 \left|\sum\limits_{j=1}^n z_j\right|+\sum\limits_{m=2}^{\infty}\left(\left|\sum\limits_{|\beta|=m}a_{\beta}\right|+\left|\sum\limits_{|\beta|=m}b_{\beta}\right|\right)r^{\beta}\leq&
 n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\binom{m+n-1}{n-1}\frac{\|z\|_{\infty}^m}{m}\\\leq&
 n{\bf{r}}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(n{\bf{r}})^m}{m}\\\leq&
 1+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{mn^m}\\=& d\left(f(0),\partial f(\mathbb{P}\Delta(0;1/n))\right).
 \end{align*}
 
