 To show that the constant ${\bf{r}}_f$ is the best possible, we consider the function $f_5(z)$ defined by 
 \begin{align*}
 	f_5(z)=\sum\limits_{j=1}^n z_j+\sum\limits_{m=2}^{\infty}\sum\limits_{|\beta|=m}a_{\beta}z^{\beta},\;\;
 	a_{\beta}=\frac{2n(1-\alpha)n^{\beta}}{\binom{m+n-1}{n-1}m}
 \end{align*}
 for $\beta=(\beta_1,\ldots,\beta_n)$ such that $|\beta|=m\geq 2$. 

 
 Let $z=(r,r,\ldots,r)$, where $nr<1$. Now using \eqref{Th5:1.5}, we deduce that

 \begin{align*}
 	&\left|\sum\limits_{j=1}^n z_j\right|+\sum\limits_{m=2}^{\infty}\left(\left|\sum\limits_{|\beta|=m}a_{\beta}\right|+\left|\sum\limits_{|\beta|=m}b_{\beta}\right|\right)r^{\beta} =
 	n\|z\|_{\infty}+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(n\|z\|_{\infty})^m}{m}\\=&
 	n{\bf{r}}_f+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(n{\bf{r}}_f)^m}{m}=
 	1+2n(1-\alpha)\sum\limits_{m=2}^{\infty}\frac{(-1)^{m-1}}{mn^m}\\=& d\left(f(0),\partial f(\mathbb{P}\Delta(0;1/n))\right)
 \end{align*}
 and hence the radius ${\bf{r}}_f$ is the best possible.

Let $f=h+\overline g\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$, where $h$ and $g$ are given by (\ref{Eq 1.7}). Note that
\begin{align*}
	S_{1,q}(f(z))=S_1(h(z))+\overline{S_q(g(z))}=\sum\limits_{j=1}^n z_j+\overline{\sum\limits_{m=2}^q\sum_{|\beta|=m}b_{\beta}z^{\beta}}.
\end{align*}

Also we see that
\begin{align*}
	\frac{\partial S_1(h(z))}{\partial z_j}=1
\end{align*}
and so 
\begin{align*}
\sum\limits_{j=1}^n\Re\left(\frac{\partial S_1(h(z))}{\partial z_j}-\alpha\right)=n(1-\alpha).
\end{align*}

On the other hand, from (\ref{Th2:1.5a}) and (\ref{Th2:1.8a}), we deduce that
\begin{align}\label{Th7:1.1}
&\sum\limits_{k=1}^n\left|\frac{\partial S_q(g(z))}{\partial z_k}\right|\\\leq&
\sum\limits_{k=1}^n\sum\limits_{m=2}^{q}\sum\limits_{|\beta|=m}\beta_{k} \left|b_{\beta}z_1^{\beta_1}\ldots z_{j-1}^{\beta_{j-1}}z_{j}^{\beta_j}z_{j+1}^{\beta_{j+1}}\ldots z_{k-1}^{\beta_{k-1}}z_{k}^{\beta_k-1}z_{k+1}^{\beta_{k+1}}\ldots z_n^{\beta_n}\right|\nonumber
\\\leq &
\sum\limits_{k=1}^n\sum\limits_{m=2}^{q}\sum\limits_{|\beta|=m}\beta_{k} \left|b_{\beta}\right|\|z\|_{\infty}^{m-1}
\nonumber\\=&
\sum\limits_{m=2}^{q}\sum\limits_{|\beta|=m}m|b_{\beta}|\|z\|_{\infty}^{m-1}\nonumber.
\end{align}
Using Theorem \ref{Th-1.2} to \eqref{Th7:1.1}, we obtain
\begin{align*}
 \sum\limits_{k=1}^n\left|\frac{\partial S_q(g(z))}{\partial z_k}\right|\leq&n(1-\alpha) \sum\limits_{m=2}^q \binom{m+n-1}{n-1}\|z\|_{\infty}^{m-1}\\\leq&n(1-\alpha)
 \sum\limits_{m=2}^q n^{m}\|z\|_{\infty}^{m-1}\\<&n(1-\alpha)
 \sum\limits_{m=2}^q  \frac{n^{m}}{2^{m-1}n^{2(m-1)}}\\\leq&n(1-\alpha)
 \sum\limits_{m=2}^q \frac{1}{2^{m-1}}\\<& n(1-\alpha)=\sum\limits_{j=1}^n\Re\left(\frac{\partial S_1(h(z))}{\partial z_j}-\alpha\right).
 \end{align*}
 
 Therefore $S_{1,q}(f)\in \mathscr{P}_{\mathcal{H}_n^0}(\alpha)$.
